import math

def eml_quad_approx(h: float, x: float) -> float:
    u = h * x
    return (2.0 / h ** 2) * (math.exp(u) - 1.0 - u)

def check(h: float) -> None:
    grid = [i / 50.0 for i in range(51)]
    worst = max(abs(eml_quad_approx(h, x) - x ** 2) for x in grid)
    bound = (4.0 / 9.0) * h
    print(f"h={h}: max error={worst:.6e}  bound={bound:.6e}  holds={worst <= bound + 1e-12}")

for h in (0.2, 0.1, 0.01):
    check(h)

